const STORE='build-an-egg-worlds-v1';
const palette=['#ff9b82','#ffd36c','#82d8bb','#82bde8','#ad9cf2','#ffb8d0','#8c8276','#f5f0e9','#52c7cf','#ff7b55'];
const themes=[['#bdebe6','#a8d88e','#8fc774'],['#dccef7','#f4c2b2','#df9e93'],['#a8dceb','#b6d59d','#91bd79'],['#ffd7a3','#efd793','#dbb65f'],['#b6d9fc','#c4e6d3','#9bcdb1']];
let worlds=loadWorlds(), route={page:'worlds',worldId:null,tab:'biomes',itemId:null}, toastTimer, soundOn=true, draftColor=palette[0], selectedTool='place';
function loadWorlds(){try{return JSON.parse(localStorage.getItem(STORE))||[]}catch{return []}}
function save(){localStorage.setItem(STORE,JSON.stringify(worlds));document.querySelector('.save-status')?.classList.add('saved')}
function uid(){return Math.random().toString(36).slice(2,10)}
function activeWorld(){return worlds.find(w=>w.id===route.worldId)}
function defaults(name='Sunny Meadow'){return{id:uid(),name,cover:'🌼',theme:Math.floor(Math.random()*themes.length),created:Date.now(),coins:0,treadmill:1,upgrades:{},biomes:[{id:uid(),name:'Sunny Meadow',ground:'#9bd18c',sky:'#bce7e6',weather:'☀️ Sunny',time:'Day',plants:'🌼 🌿 🌷',music:'Gentle morning',eggs:[]}],eggs:[makeEgg('Sprinkle Egg')],animals:[makeCreature('Pip','animal')],guards:[makeCreature('Bramble','guard')],hatched:0,incubating:0,playSeconds:0}}
function makeEgg(name='New Egg'){return{id:uid(),name,shape:'Round',color:palette[Math.floor(Math.random()*palette.length)],blocks:eggBlocks(),hatch:30,rarity:'Common',luck:2,bonus:10}}
function eggBlocks(){const a=[];for(let y=0;y<5;y++){let width=[1,3,5,5,3][y];for(let x=0;x<width;x++)a.push({x,y,c:palette[(x+y)%palette.length],type:'shell'})}return a}
function makeCreature(name='New Friend',kind='animal'){let blocks=[];for(let x=1;x<4;x++)for(let y=1;y<4;y++)blocks.push({x,y,c:palette[(x+y)%palette.length]});blocks.push({x:2,y:0,c:'#fff0df'},{x:1,y:4,c:'#927a67'},{x:3,y:4,c:'#927a67'});return{id:uid(),name,blocks,color:'#ffb98e',speed:3,luck:2,coinRate:2,rarity:'Common',role:'Protector',health:5,power:2,range:3}}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function render(){const app=document.getElementById('app');if(route.page==='worlds')app.innerHTML=worldsView();else if(route.page==='editor')app.innerHTML=editorView();else if(route.page==='builder')app.innerHTML=builderView();else if(route.page==='play')app.innerHTML=playView();bind();}
function worldsView(){return `<div class="page-head"><div><div class="eyebrow">A cozy little sandbox</div><h1>Your worlds <span style="color:#ffab52">✦</span></h1><p>Dream it, build it, then hop right in.</p></div><button class="primary-btn" data-action="create-world">＋ Create new world</button></div><div class="stats-row"><span class="stat-pill"><b>${worlds.length}</b> worlds made</span><span class="stat-pill"><b>∞</b> room to imagine</span><span class="stat-pill">🌱 Everything is free to build</span></div>${worlds.length?`<div class="world-grid">${worlds.map(worldCard).join('')}<button class="create-card" data-action="create-world"><span class="create-plus">＋</span><strong>Dream up another world</strong><span>Make something wonderful</span></button></div>`:`<div class="empty"><span>🌱</span><h3>Your first world is waiting</h3><p>Create a cozy place, then fill it with things you build.</p><button class="primary-btn" data-action="create-world">＋ Create your first world</button></div>`}<div class="bottom-tip"><span style="font-size:20px">💛</span><span><b>Your creativity is always free.</b> No ads, no paywalls, no gems — just your imagination, saved right here on this device.</span></div>`}
function worldCard(w){let t=themes[w.theme%themes.length];return `<article class="world-card" data-world="${w.id}"><div class="world-cover" style="--sky:${t[0]};--ground:${t[1]};--ground2:${t[2]}"><span class="cover-badge">${w.biomes.length} BIOME${w.biomes.length===1?'':'S'}</span><div class="landscape">🌳　🌷　🌳</div><div class="cover-egg">${w.cover}</div></div><div class="world-content"><div class="world-title-row"><h3>${esc(w.name)}</h3><button class="dots" data-action="world-menu" data-id="${w.id}" aria-label="World options">···</button></div><div class="world-meta">${w.biomes.length} biomes · ${w.eggs.length} eggs · ${w.animals.length} friends</div><div class="world-footer"><div class="mini-tags"><span class="tag">🌈 Cozy</span><span class="tag">${w.hatched||0} hatched</span></div><button class="world-open" data-action="open-world" data-id="${w.id}">Open world →</button></div></div></article>`}

function editorView(){let w=activeWorld();if(!w)return worldsView();const tabs=[['biomes','🌿','Biomes',w.biomes],['eggs','🥚','Eggs',w.eggs],['animals','🐾','Animals',w.animals],['guards','🛡️','Guards',w.guards]];let title={biomes:'Your biomes',eggs:'Your eggs',animals:'Your animal friends',guards:'Your guards'}[route.tab];let collection=w[route.tab];return `<div class="editor-shell"><button class="back-link" data-action="home">← My worlds</button><div class="editor-title"><div><div class="eyebrow">${esc(w.name)}</div><h1>Build your world <span style="color:#ffad55">✦</span></h1><p>Every piece is yours to make. Go wild — building is always free.</p></div><button class="primary-btn" data-action="play-world">▶ Play world</button></div><div class="tabs">${tabs.map(([id,ico,label])=>`<button class="tab ${route.tab===id?'active':''}" data-action="tab" data-tab="${id}">${ico} ${label} <span style="opacity:.65">${w[id].length}</span></button>`).join('')}</div><div class="panel-heading" style="background:white;border:1px solid #f0ece7;border-radius:14px;margin-bottom:12px"><strong>${title}</strong><button class="soft-btn" data-action="add-item">＋ Create ${route.tab==='biomes'?'biome':route.tab==='eggs'?'egg':route.tab==='animals'?'animal':'guard'}</button></div><div class="section-grid">${collection.map(item=>itemCard(item,route.tab)).join('')}<button class="section-card" data-action="add-item"><span class="section-icon">＋</span><strong>Create a new ${route.tab==='biomes'?'biome':route.tab==='eggs'?'egg':route.tab==='animals'?'animal':'guard'}</strong><p>Start from a blank canvas and make it your own.</p><small>100% FREE · NO LIMITS</small></button></div><div class="bottom-tip"><span style="font-size:19px">✨</span><span><b>Over 10 trillion combinations.</b> Mix shapes, patterns, colors, parts, and accessories to make a one-of-a-kind world.</span></div></div>`}
function itemCard(it,type){let ico=type==='biomes'?'🌱':type==='eggs'?'🥚':type==='animals'?'🐾':'🛡️';let count=type==='eggs'?`${it.blocks?.length||0} blocks · ${it.rarity||'Common'}`:type==='biomes'?`${it.weather||'☀️ Sunny'} · ${it.time||'Day'}`:`${it.blocks?.length||0} blocks · ${it.rarity||'Common'}`;return `<button class="section-card" data-action="edit-item" data-type="${type}" data-id="${it.id}"><span class="section-icon">${ico}</span><strong>${esc(it.name)}</strong><p>${count}</p><small>✎ TAP TO EDIT</small></button>`}
function builderView(){let w=activeWorld(),type=route.tab,it=w?.[type]?.find(x=>x.id===route.itemId);if(!w||!it){route.page='editor';return editorView()}let isEgg=type==='eggs',kind=type==='animals'?'animal':'guard',blocks=it.blocks||[], label=isEgg?'egg':kind;let blockHTML=blocks.map((b,i)=>`<span class="block ${b.type==='glow'?'glow':''}" data-block="${i}" style="--c:${b.c};left:${b.x*38+32}px;top:${b.y*37+19}px" title="Tap to paint"></span>`).join('');let swatches=palette.map(c=>`<button class="swatch ${draftColor===c?'selected':''}" data-action="color" data-color="${c}" style="background:${c}" aria-label="${c}"></button>`).join('');return `<div class="editor-shell"><button class="back-link" data-action="back-editor">← ${esc(w.name)} / ${type}</button><div class="editor-title"><div><div class="eyebrow">${isEgg?'Block-built egg':kind==='animal'?'Voxel animal':'Block-built guard'}</div><h1>${esc(it.name)} <span style="color:#ffab52">✦</span></h1><p>Tap the blocks to paint · drag to spin your creation</p></div><button class="primary-btn" data-action="save-item">✓ Save ${label}</button></div><div class="editor-layout"><div class="panel"><div class="panel-heading"><strong>🧊 Block studio</strong><span>${isEgg?'EGG GRID':kind.toUpperCase()+' · 16 × 16 × 16'}</span></div><div class="builder-toolbar"><button class="tool-btn ${selectedTool==='place'?'active':''}" data-action="tool" data-tool="place">＋ Place</button><button class="tool-btn ${selectedTool==='delete'?'active':''}" data-action="tool" data-tool="delete">⌫ Delete</button><button class="tool-btn ${selectedTool==='paint'?'active':''}" data-action="tool" data-tool="paint">🎨 Paint</button><button class="tool-btn" data-action="mirror">⇋ Mirror</button><button class="tool-btn" data-action="undo">↶ Undo</button></div><div class="scene" id="scene"><div class="scene-controls"><button data-action="rotate">⟳ Rotate</button><button data-action="zoom">＋</button></div><div class="voxel" id="voxel">${blockHTML}</div><div class="scene-hint">✋ Drag to rotate · tap a block to paint · pinch to zoom</div></div><div class="builder-foot"><button class="secondary-btn" data-action="randomize">✨ Randomize</button><button class="secondary-btn" data-action="duplicate">▣ Duplicate</button><button class="secondary-btn" data-action="clear">⌫ Clear</button><button class="primary-btn" data-action="preview">▶ Preview</button></div></div><div class="panel side-panel"><label class="field-label" for="itemName">${label} name</label><input id="itemName" class="text-input" value="${esc(it.name)}" maxlength="28"><label class="field-label">Block color · HSV palette</label><div class="color-row">${swatches}</div><div class="palette-custom"><input type="color" id="customColor" value="${draftColor}" aria-label="Color wheel"><input class="text-input" id="hexColor" value="${draftColor}" style="padding:8px;font-family:monospace;text-transform:uppercase" maxlength="7"><button class="tool-btn" data-action="eyedrop">◎</button></div><label class="field-label">Saturation <span id="satVal">100%</span></label><div class="range-row"><span>Muted</span><input type="range" min="0" max="100" value="100" id="saturation"><span>Vivid</span></div><label class="field-label">Brightness <span id="brightVal">100%</span></label><div class="range-row"><span>Soft</span><input type="range" min="20" max="130" value="100" id="brightness"><span>Bright</span></div>${isEgg?`<label class="field-label">Shape</label><div class="shape-pills">${['Round','Oval','Tall','Square','Spiky','Crystal','Long','Tiny','Giant'].map(s=>`<button class="shape-pill ${it.shape===s?'active':''}" data-action="shape" data-value="${s}">${s}</button>`).join('')}</div><div class="stat-line"><span>Hatch time</span><b>${it.hatch||30}s</b></div><div class="stat-line"><span>Rarity · Luck · Bonus</span><b>${it.rarity||'Common'} · ${it.luck||2} · 🪙${it.bonus||10}</b></div>`:type==='animals'?`<label class="field-label">Friend stats</label><div class="stat-line"><span>⚡ Speed</span><b>${it.speed||3}</b></div><div class="stat-line"><span>🍀 Luck · 🪙 Coin rate</span><b>${it.luck||2} · ${it.coinRate||2}/s</b></div><div class="stat-line"><span>Rarity</span><b>${it.rarity||'Common'}</b></div>`:`<label class="field-label">Guard role</label><select class="select-input" id="guardRole">${['Protector','Patroller','Runner','Egg Sitter'].map(r=>`<option ${it.role===r?'selected':''}>${r}</option>`).join('')}</select><div class="stat-line"><span>❤️ Health · ⚡ Speed</span><b>${it.health||5} · ${it.speed||3}</b></div><div class="stat-line"><span>⚔ Power · 🛡 Range</span><b>${it.power||2} · ${it.range||3}</b></div>`}<p class="editor-hint">💡 Every block can be placed, painted, or deleted. Your creation saves on this device.</p></div></div></div>`}

function playView(){let w=activeWorld();if(!w){route.page='worlds';return worldsView()}let earned=Math.floor((w.playSeconds||0)/2);w.coins+=Math.max(0,earned-(w._earned||0));w._earned=earned;save();let income=1+((w.upgrades.treadmill||0)*.6);return `<div class="editor-shell"><button class="back-link" data-action="back-editor">← ${esc(w.name)}</button><div class="play-top"><div class="play-stat coin">🪙 <b id="coinCount">${w.coins}</b> coins</div><div class="play-stat">⚡ Speed <b>${income.toFixed(1)}×</b></div><div class="play-stat">🏃 Treadmill <b>Lv. ${w.treadmill||1}</b></div><div class="play-stat" style="margin-left:auto">☀️ ${w.biomes[0]?.weather||'Sunny'}</div></div><div class="play-scene"><div class="sun"></div><div class="cloud">☁️</div><div class="play-hills"></div><div class="play-hills second"></div><div class="tree left">🌳</div><div class="tree right">🌲</div><div class="base-platform"></div><div class="incubator one" data-action="incubate">${w.incubating?'🥚':'＋'}</div><div class="incubator two" data-action="incubate">${w.eggs[0]?'🥚':'＋'}</div><div class="incubator three" data-action="incubate">${w.eggs[1]?'🥚':'＋'}</div><div class="treadmill">〰️ 〰️ 〰️</div><div class="runner">🐣</div><div class="guard">🛡️</div><div class="play-character">🐥</div><div class="coin-float">+${income.toFixed(1)} 🪙</div><div class="play-actions"><button data-action="hatch">🥚 Hatch egg</button><button data-action="collect">🪙 Collect</button></div></div><div class="play-bottom"><button class="primary-btn" data-action="earn">⚡ Play & earn coins</button><button class="secondary-btn" data-action="upgrade">🏃 Upgrade treadmill · ${upgradeCost(w)} coins</button><button class="secondary-btn" data-action="train">🐾 Train a friend · ${trainCost(w)} coins</button><button class="secondary-btn" data-action="open-guard-upgrade">🛡️ Guard upgrades</button></div><div class="bottom-tip"><span style="font-size:20px">🌱</span><span><b>Just play to earn.</b> Your treadmill brings in coins over time. Every upgrade costs only in-game coins — no real money, ever.</span></div></div>`}
function upgradeCost(w){return 20+(w.treadmill||1)*20}function trainCost(w){return 15+(w.animals[0]?.speed||3)*8}
function toast(msg){let el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function openModal(html){document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" data-action="backdrop"><div class="modal">${html}</div></div>`}
function closeModal(){document.getElementById('modalRoot').innerHTML=''}
function newWorldModal(){openModal(`<div class="modal-head"><h2>Make a little world 🌱</h2><button class="modal-close" data-action="close">×</button></div><p>Name your world and pick a cozy cover. You can change everything later.</p><label class="field-label">World name</label><input id="newWorldName" class="text-input" placeholder="e.g. Cloudberry Cove" maxlength="28" value="Cloudberry Cove"><label class="field-label">Choose a cover buddy</label><div class="emoji-picker">${['🥚','🌼','🐣','🦋','🍄','🌈','🦊','🐸','🪺','🐧','🐢','🌷'].map(e=>`<button class="emoji-choice" data-action="choose-cover" data-emoji="${e}">${e}</button>`).join('')}</div><div class="modal-buttons"><button class="secondary-btn" data-action="close">Maybe later</button><button class="primary-btn" data-action="confirm-world">Create my world ✨</button></div>`);document.querySelector('.emoji-choice')?.classList.add('selected')}
function itemModal(){let type=route.tab,w=activeWorld();if(type==='biomes'){openBiomeModal();return}let isEgg=type==='eggs';let label=type==='eggs'?'egg':type==='animals'?'animal':'guard';openModal(`<div class="modal-head"><h2>Build a ${label} ${isEgg?'🥚':type==='animals'?'🐾':'🛡️'}</h2><button class="modal-close" data-action="close">×</button></div><p>Start from a blank, block-by-block creation — make it yours.</p><label class="field-label">Give it a name</label><input id="newItemName" class="text-input" maxlength="26" placeholder="A lovely name" value="${isEgg?'Twinkle Egg':type==='animals'?'Pudding':'Acorn Guard'}">${isEgg?`<label class="field-label">Choose a starting shell color</label><div class="color-row">${palette.map(c=>`<button class="swatch ${c===draftColor?'selected':''}" data-action="color" data-color="${c}" style="background:${c}"></button>`).join('')}</div>`:''}<div class="modal-buttons"><button class="secondary-btn" data-action="close">Cancel</button><button class="primary-btn" data-action="confirm-item">Open block studio →</button></div>`)}
function openBiomeModal(id){let w=activeWorld(),b=id?w.biomes.find(x=>x.id===id):null;openModal(`<div class="modal-head"><h2>${b?'Edit biome':'Build a biome'} 🌿</h2><button class="modal-close" data-action="close">×</button></div><p>Design a place for your eggs and friends to call home.</p><label class="field-label">Biome name</label><input id="biomeName" class="text-input" maxlength="26" value="${esc(b?.name||'Mushroom Meadow')}" placeholder="A lovely place"><div class="biome-preview" id="biomePreview">🌳　🌷　🪨　🌿</div><div class="world-edit-grid"><div><label class="field-label">Ground color</label><input id="groundColor" class="text-input" type="color" value="${b?.ground||'#9bd18c'}"></div><div><label class="field-label">Sky color</label><input id="skyColor" class="text-input" type="color" value="${b?.sky||'#bce7e6'}"></div><div><label class="field-label">Ground type</label><select class="select-input" id="groundType"><option>Soft grass</option><option>Flower meadow</option><option>Sand</option><option>Snow</option><option>Mossy stone</option><option>Crystal</option></select></div><div><label class="field-label">Time of day</label><select class="select-input" id="biomeTime">${['Day','Sunset','Night','Dawn'].map(x=>`<option ${b?.time===x?'selected':''}>${x}</option>`).join('')}</select></div><div><label class="field-label">Weather</label><select class="select-input" id="biomeWeather">${['☀️ Sunny','🌤️ Breezy','🌧️ Gentle rain','❄️ Snowfall','🌈 Rainbow'].map(x=>`<option ${b?.weather===x?'selected':''}>${x}</option>`).join('')}</select></div><div><label class="field-label">Background music</label><select class="select-input" id="biomeMusic"><option>Gentle morning</option><option>Cozy rain</option><option>Twilight song</option><option>Forest friends</option><option>Quiet pond</option></select></div></div><label class="field-label">Plants & decorations</label><input id="biomePlants" class="text-input" maxlength="40" value="${esc(b?.plants||'🌼 🌿 🌷 🌳 🪨')}"><div class="modal-buttons"><button class="secondary-btn" data-action="close">Cancel</button><button class="primary-btn" data-action="save-biome">${b?'Save biome':'Create biome ✨'}</button></div>`);let gc=document.getElementById('groundColor'),sc=document.getElementById('skyColor');[gc,sc].forEach(el=>el.addEventListener('input',()=>document.getElementById('biomePreview').style.background=`linear-gradient(180deg,${sc.value} 0 55%,${gc.value} 56%)`))}

function bind(){document.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',handle));document.querySelectorAll('.world-card').forEach(el=>el.addEventListener('click',e=>{if(e.target.closest('[data-action]'))return;route.worldId=el.dataset.world;route.page='editor';route.tab='biomes';render()}));document.querySelectorAll('[data-block]').forEach(el=>el.addEventListener('click',e=>{e.stopPropagation();blockTap(+el.dataset.block)}));document.getElementById('itemName')?.addEventListener('input',e=>{let it=getCurrentItem();if(it)it.name=e.target.value});document.getElementById('customColor')?.addEventListener('input',e=>setColor(e.target.value));document.getElementById('hexColor')?.addEventListener('change',e=>{if(/^#[0-9a-f]{6}$/i.test(e.target.value))setColor(e.target.value)});document.getElementById('saturation')?.addEventListener('input',e=>document.getElementById('satVal').textContent=e.target.value+'%');document.getElementById('brightness')?.addEventListener('input',e=>document.getElementById('brightVal').textContent=e.target.value+'%');let sc=document.getElementById('scene'),vx=document.getElementById('voxel');if(sc&&vx){let down=false,lastX=0;sc.addEventListener('pointerdown',e=>{down=true;lastX=e.clientX;sc.setPointerCapture(e.pointerId)});sc.addEventListener('pointermove',e=>{if(!down)return;let dx=e.clientX-lastX;lastX=e.clientX;let a=+(vx.dataset.angle||-13)+dx*.8;vx.dataset.angle=a;vx.style.transform=`rotate(${a}deg)`});sc.addEventListener('pointerup',()=>down=false)}}
function getCurrentItem(){let w=activeWorld();return w?.[route.tab]?.find(x=>x.id===route.itemId)}
function setColor(c){draftColor=c;document.getElementById('hexColor').value=c;document.getElementById('customColor').value=c;let w=activeWorld(),it=getCurrentItem();if(it){it.color=c;render()}else document.querySelectorAll('.swatch').forEach(s=>s.classList.toggle('selected',s.dataset.color===c))}
function blockTap(i){let it=getCurrentItem();if(!it)return;let b=it.blocks[i];if(selectedTool==='delete'){it.blocks.splice(i,1)}else if(selectedTool==='place'){it.blocks.push({x:Math.floor(Math.random()*5),y:Math.floor(Math.random()*5),c:draftColor})}else if(b)b.c=draftColor;save();render()}
function handle(e){let el=e.currentTarget,act=el.dataset.action,id=el.dataset.id,w=activeWorld();if(e.target.closest('.modal')===null&&el.classList.contains('modal-backdrop')&&act==='backdrop'){closeModal();return}switch(act){case'home':route={page:'worlds',worldId:null,tab:'biomes'};render();break;case'create-world':newWorldModal();break;case'close':closeModal();break;case'choose-cover':document.querySelectorAll('.emoji-choice').forEach(x=>x.style.outline='');el.style.outline='2px solid #ff8069';break;case'confirm-world':{let name=document.getElementById('newWorldName').value.trim()||'My Little World',cover=document.querySelector('.emoji-choice[style*="outline"]')?.dataset.emoji||'🥚';let nw=defaults(name);nw.cover=cover;worlds.unshift(nw);save();route={page:'editor',worldId:nw.id,tab:'biomes'};closeModal();render();toast('Your new world is ready! 🌱');break}case'world-menu':e.stopPropagation();route.worldId=id;openModal(`<div class="modal-head"><h2>${esc(worlds.find(x=>x.id===id).name)}</h2><button class="modal-close" data-action="close">×</button></div><p>What would you like to do with this world?</p><div class="world-options"><button class="secondary-btn" data-action="rename-world" data-id="${id}">✎ Rename</button><button class="secondary-btn" data-action="edit-cover" data-id="${id}">🎨 Cover</button></div><div class="world-options"><button class="soft-btn" data-action="delete-world" data-id="${id}">⌫ Delete world</button><button class="primary-btn" data-action="open-world" data-id="${id}">Open →</button></div>`);bind();break;case'open-world':route.worldId=id||route.worldId;route.page='editor';route.tab='biomes';closeModal();render();break;case'rename-world':{let nw=worlds.find(x=>x.id===id);openModal(`<div class="modal-head"><h2>Rename your world ✎</h2><button class="modal-close" data-action="close">×</button></div><label class="field-label">World name</label><input id="renameWorld" class="text-input" value="${esc(nw.name)}" maxlength="28"><div class="modal-buttons"><button class="secondary-btn" data-action="close">Cancel</button><button class="primary-btn" data-action="save-world-name" data-id="${id}">Save name</button></div>`);bind();break}case'save-world-name':worlds.find(x=>x.id===id).name=document.getElementById('renameWorld').value.trim()||'Little World';save();closeModal();render();toast('World name saved ✨');break;case'edit-cover':{let nw=worlds.find(x=>x.id===id);openModal(`<div class="modal-head"><h2>Pick a world cover 🎨</h2><button class="modal-close" data-action="close">×</button></div><div class="emoji-picker">${['🥚','🌼','🐣','🦋','🍄','🌈','🦊','🐸','🪺','🐧','🐢','🌷'].map(x=>`<button class="emoji-choice ${nw.cover===x?'selected':''}" data-action="set-cover" data-id="${id}" data-emoji="${x}">${x}</button>`).join('')}</div>`);bind();break}case'set-cover':worlds.find(x=>x.id===id).cover=el.dataset.emoji;save();closeModal();render();break;case'delete-world':{let nw=worlds.find(x=>x.id===id);openModal(`<div class="modal-head"><h2>Delete ${esc(nw.name)}?</h2><button class="modal-close" data-action="close">×</button></div><p>This removes this world and everything inside it from this device. This cannot be undone.</p><div class="modal-buttons"><button class="secondary-btn" data-action="close">Keep world</button><button class="soft-btn" data-action="confirm-delete" data-id="${id}">Delete world</button></div>`);bind();break}case'confirm-delete':worlds=worlds.filter(x=>x.id!==id);save();route={page:'worlds',worldId:null,tab:'biomes'};closeModal();render();toast('World removed');break;case'tab':route.tab=el.dataset.tab;render();break;case'add-item':itemModal();break;case'confirm-item':{let name=document.getElementById('newItemName').value.trim()||'Little creation';let item=route.tab==='eggs'?makeEgg(name):makeCreature(name,route.tab==='animals'?'animal':'guard');if(route.tab==='eggs')item.color=draftColor;w[route.tab].push(item);route.itemId=item.id;route.page='builder';closeModal();save();render();toast('Blank block studio ready!