1.12)';setTimeout(()=>{if(vx.isConnected)vx.style.transform='rotate(347deg)'},900);toast('Looking lovely! ✨');break}case'rotate':{let vx=document.getElementById('voxel');let a=+(vx.dataset.angle||-13)+90;vx.dataset.angle=a;vx.style.transform=`rotate(${a}deg)`;break}case'zoom':{let vx=document.getElementById('voxel');vx.style.scale='1.15';break}case'mirror':{let it=getCurrentItem();it.blocks.forEach(b=>b.x=4-(b.x||0));save();render();toast('Mirrored! ⇋');break}case'undo':toast('One more block? Tap Clear to restart this design.');break;case'shape':{let it=getCurrentItem();it.shape=el.dataset.value;document.querySelectorAll('.shape-pill').forEach(x=>x.classList.toggle('active',x===el));toast(`${it.shape} shape selected`);save();break}case'eyedrop':{let it=getCurrentItem();if(it.blocks.length)setColor(it.blocks[Math.floor(Math.random()*it.blocks.length)].c);else toast('Place a block to pick its color');break}case'play-world':route.page='play';w.playSeconds=(w.playSeconds||0);save();render();if(!localStorage.getItem('egg-tutorial-seen'))tutorial();break;case'back-editor':route.page='editor';render();break;case'earn':{w.coins+=5;w.playSeconds=(w.playSeconds||0)+10;save();document.getElementById('coinCount').textContent=w.coins;toast('Great play! +5 coins 🪙');break}case'upgrade':{let cost=upgradeCost(w);if(w.coins<cost){toast(`Need ${cost} coins — play a little more!`);break}w.coins-=cost;w.treadmill=(w.treadmill||1)+1;w.upgrades.treadmill=(w.upgrades.treadmill||0)+1;save();render();toast(`Treadmill upgraded to level ${w.treadmill}! 🏃`);break}case'train':{let cost=trainCost(w);if(w.coins<cost){toast(`Need ${cost} coins — keep playing!`);break}w.coins-=cost;if(w.animals[0])w.animals[0].speed++;save();render();toast('Your friend trained up! ⚡');break}case'collect':w.coins+=3;save();document.getElementById('coinCount').textContent=w.coins;toast('+3 coins collected! 🪙');break;case'incubate':if(!w.eggs.length){toast('Build an egg in your world first!');break}w.incubating=1;save();toast('Egg placed in the incubator 🥚');break;case'hatch':if(!w.eggs.length){toast('Build an egg in your world first!');break}w.incubating=0;w.hatched++;w.coins+=(w.eggs[0].bonus||10);save();render();toast('Crack! A new friend hatched! 🎉');break;case'open-guard-upgrade':{let cost=25;openModal(`<div class="modal-head"><h2>Guard training 🛡️</h2><button class="modal-close" data-action="close">×</button></div><p>Strengthen the guard who watches over your cozy base.</p><div class="stat-line"><span>❤️ Health · ⚡ Patrol speed · 🛡 Range</span><b>+1 each</b></div><div class="modal-buttons"><button class="secondary-btn" data-action="close">Later</button><button class="primary-btn" data-action="upgrade-guard">Train · ${cost} coins</button></div>`);break}case'upgrade-guard':if(w.coins<25){toast('Need 25 coins — play to earn them!');closeModal();break}w.coins-=25;w.guards[0].health++;w.guards[0].speed++;save();closeModal();render();toast('Guard is stronger now! 🛡️');break;case'tutorial':tutorial();break}}
