const STORE='build-an-egg-worlds-v1', palette=['#ff9b82','#ffd36c','#82d8bb','#82bde8','#ad9cf2','#ffb8d0','#8c8276','#f5f0e9','#52c7cf','#ff7b55'];
const themes=[['#bdebe6','#a8d88e','#8fc774'],['#dccef7','#f4c2b2','#df9e93'],['#a8dceb','#b6d59d','#91bd79'],['#ffd7a3','#efd793','#dbb65f']];
let worlds=load(), route={page:'worlds',worldId:null,tab:'biomes',itemId:null}, draftColor=palette[0], tool='paint', history=[], timer;
function load(){try{return JSON.parse(localStorage.getItem(STORE))||[]}catch{return []}}
function save(){localStorage.setItem(STORE,JSON.stringify(worlds))}
function uid(){return Math.random().toString(36).slice(2,10)}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function world(){return worlds.find(w=>w.id===route.worldId)}
function egg(name='Sprinkle Egg'){return{id:uid(),name,shape:'Round',color:palette[0],blocks:Array.from({length:17},(_,i)=>({x:i%5,y:Math.floor(i/5),c:palette[i%palette.length]})),hatch:30,rarity:'Common',luck:2,bonus:10}}
function creature(name,guard=false){return{id:uid(),name,blocks:Array.from({length:13},(_,i)=>({x:i%4,y:Math.floor(i/4),c:palette[i%palette.length]})),color:'#ffb98e',speed:3,luck:2,coinRate:2,rarity:'Common',role:'Protector',health:5,power:2,range:3}}
function makeWorld(name='Sunny Meadow'){return{id:uid(),name,cover:'🥚',theme:Math.floor(Math.random()*themes.length),coins:0,treadmill:1,upgrades:{},biomes:[{id:uid(),name:'Sunny Meadow',ground:'#9bd18c',sky:'#bce7e6',weather:'☀️ Sunny',time:'Day',plants:'🌼 🌿 🌷',music:'Gentle morning',eggs:[]}],eggs:[egg()],animals:[creature('Pip')],guards:[creature('Bramble',true)],hatched:0,playSeconds:0,_earned:0}}
function app(){return document.getElementById('app')}
function render(){if(route.page==='worlds')app().innerHTML=worldsView();if(route.page==='editor')app().innerHTML=editorView();if(route.page==='builder')app().innerHTML=builderView();if(route.page==='play')app().innerHTML=playView();bind()}
function worldsView(){return `<div class="page-head"><div><div class="eyebrow">A cozy little sandbox</div><h1>Your worlds <span style="color:#ffab52">✦</span></h1><p>Dream it, build it, then hop right in.</p></div><button class="primary-btn" data-a="new-world">＋ Create new world</button></div><div class="stats-row"><span class="stat-pill"><b>${worlds.length}</b> worlds made</span><span class="stat-pill"><b>∞</b> room to imagine</span><span class="stat-pill">🌱 Everything is free to build</span></div><div class="world-grid">${worlds.map(w=>{let t=themes[w.theme%themes.length];return `<article class="world-card" data-open="${w.id}"><div class="world-cover" style="--sky:${t[0]};--ground:${t[1]};--ground2:${t[2]}"><span class="cover-badge">${w.biomes.length} BIOME${w.biomes.length===1?'':'S'}</span><div class="landscape">🌳　🌷　🌳</div><div class="cover-egg">${w.cover}</div></div><div class="world-content"><div class="world-title-row"><h3>${esc(w.name)}</h3><button class="dots" data-a="world-menu" data-id="${w.id}">···</button></div><div class="world-meta">${w.biomes.length} biomes · ${w.eggs.length} eggs · ${w.animals.length} friends</div><div class="world-footer"><div class="mini-tags"><span class="tag">🌈 Cozy</span><span class="tag">${w.hatched} hatched</span></div><button class="world-open" data-a="open" data-id="${w.id}">Open world →</button></div></div></article>`}).join('')}<button class="create-card" data-a="new-world"><span class="create-plus">＋</span><strong>Dream up another world</strong><span>Make something wonderful</span></button></div><div class="bottom-tip"><span>💛</span><span><b>Your creativity is always free.</b> No ads, no paywalls, no gems — just your imagination, saved right here on this device.</span></div>`}
function editorView(){let w=world();if(!w)return '';let names={biomes:'Biomes',eggs:'Eggs',animals:'Animals',guards:'Guards'},items=w[route.tab];return `<div class="editor-shell"><button class="back-link" data-a="home">← My worlds</button><div class="editor-title"><div><div class="eyebrow">${esc(w.name)}</div><h1>Build your world <span style="color:#ffab52">✦</span></h1><p>Every piece is yours to make. Go wild — building is always free.</p></div><button class="primary-btn" data-a="play">▶ Play world</button></div><div class="tabs">${Object.keys(names).map(k=>`<button class="tab ${route.tab===k?'active':''}" data-a="tab" data-tab="${k}">${({biomes:'🌿',eggs:'🥚',animals:'🐾',guards:'🛡️'})[k]} ${names[k]} ${w[k].length}</button>`).join('')}</div><div class="panel-heading" style="background:white;border:1px solid #f0ece7;border-radius:14px;margin-bottom:12px"><strong>Your ${names[route.tab].toLowerCase()}</strong><button class="soft-btn" data-a="add">＋ Create ${route.tab.slice(0,-1)}</button></div><div class="section-grid">${items.map(it=>`<button class="section-card" data-a="edit-item" data-type="${route.tab}" data-id="${it.id}"><span class="section-icon">${({biomes:'🌱',eggs:'🥚',animals:'🐾',guards:'🛡️'})[route.tab]}</span><strong>${esc(it.name)}</strong><p>${route.tab==='biomes'?`${it.weather||'☀️ Sunny'} · ${it.time||'Day'}`:`${it.blocks?.length||0} blocks · ${it.rarity||'Common'}`}</p><small>✎ TAP TO EDIT</small></button>`).join('')}<button class="section-card" data-a="add"><span class="section-icon">＋</span><strong>Create a new ${route.tab.slice(0,-1)}</strong><p>Start from a blank canvas and make it your own.</p><small>100% FREE · NO LIMITS</small></button></div><div class="bottom-tip"><span>✨</span><span><b>Over 10 trillion combinations.</b> Mix shapes, patterns, colors, parts, and accessories.</span></div></div>`}

