const KEY='build-an-egg-worlds-v1';
const COLORS=['#ff9b82','#ffd36c','#82d8bb','#82bde8','#ad9cf2','#ffb8d0','#8c8276','#f5f0e9','#52c7cf','#ff7b55'];
const THEMES=[['#bdebe6','#a8d88e','#8fc774'],['#dccef7','#f4c2b2','#df9e93'],['#a8dceb','#b6d59d','#91bd79'],['#ffd7a3','#efd793','#dbb65f']];
let worlds=readSave(), state={page:'worlds',worldId:null,tab:'biomes',itemId:null}, color=COLORS[0], tool='paint', history=[], timer;
function readSave(){try{return JSON.parse(localStorage.getItem(KEY))||[]}catch{return []}}
function save(){try{localStorage.setItem(KEY,JSON.stringify(worlds))}catch{};const status=document.querySelector('.save-status');if(status)status.title='Saved just now'}
function id(){return Math.random().toString(36).slice(2,10)}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function current(){return worlds.find(w=>w.id===state.worldId)}
function newEgg(name='Sprinkle Egg'){return{id:id(),name,shape:'Round',color:COLORS[0],blocks:Array.from({length:17},(_,i)=>({x:i%5,y:Math.floor(i/5),c:COLORS[i%COLORS.length],type:'shell'})),hatch:30,rarity:'Common',luck:2,bonus:10}}
function newFriend(name,guard=false){const blocks=[];for(let x=1;x<4;x++)for(let y=1;y<4;y++)blocks.push({x,y,c:COLORS[(x+y)%COLORS.length]});blocks.push({x:2,y:0,c:'#fff0df'},{x:1,y:4,c:'#927a67'},{x:3,y:4,c:'#927a67'});return{id:id(),name,blocks,color:'#ffb98e',speed:3,luck:2,coinRate:2,rarity:'Common',role:'Protector',health:5,power:2,range:3}}
function newWorld(name='Sunny Meadow'){return{id:id(),name,cover:'🌼',theme:Math.floor(Math.random()*THEMES.length),coins:0,treadmill:1,upgrades:{},biomes:[{id:id(),name:'Sunny Meadow',ground:'#9bd18c',sky:'#bce7e6',weather:'☀️ Sunny',time:'Day',plants:'🌼 🌿 🌷 🌳',music:'Gentle morning',eggs:[]}],eggs:[newEgg()],animals:[newFriend('Pip')],guards:[newFriend('Bramble',true)],hatched:0,playSeconds:0,_earned:0}}
function render(){const root=document.getElementById('app');root.innerHTML=state.page==='worlds'?worldsView():state.page==='editor'?editorView():state.page==='builder'?builderView():playView();bind()}
function worldsView(){return `<div class="page-head"><div><div class="eyebrow">A cozy little sandbox</div><h1>Your worlds <span style="color:#ffab52">✦</span></h1><p>Dream it, build it, then hop right in.</p></div><button class="primary-btn" data-action="create-world">＋ Create new world</button></div><div class="stats-row"><span class="stat-pill"><b>${worlds.length}</b> worlds made</span><span class="stat-pill"><b>∞</b> room to imagine</span><span class="stat-pill">🌱 Everything is free to build</span></div>${worlds.length?`<div class="world-grid">${worlds.map(worldCard).join('')}<button class="create-card" data-action="create-world"><span class="create-plus">＋</span><strong>Dream up another world</strong><span>Make something wonderful</span></button></div>`:`<div class="empty"><span>🌱</span><h3>Your first world is waiting</h3><p>Create a cozy place, then fill it with things you build.</p><button class="primary-btn" data-action="create-world">＋ Create your first world</button></div>`}<div class="bottom-tip"><span style="font-size:20px">💛</span><span><b>Your creativity is always free.</b> No ads, no paywalls, no gems — just your imagination, saved right here on this device.</span></div>`}
function worldCard(w){const t=THEMES[w.theme%THEMES.length];return `<article class="world-card" data-world="${w.id}"><div class="world-cover" style="--sky:${t[0]};--ground:${t[1]};--ground2:${t[2]}"><span class="cover-badge">${w.biomes.length} BIOME${w.biomes.length===1?'':'S'}</span><div class="landscape">🌳　🌷　🌳</div><div class="cover-egg">${w.cover}</div></div><div class="world-content"><div class="world-title-row"><h3>${esc(w.name)}</h3><button class="dots" data-action="world-menu" data-id="${w.id}">···</button></div><div class="world-meta">${w.biomes.length} biomes · ${w.eggs.length} eggs · ${w.animals.length} friends</div><div class="world-footer"><div class="mini-tags"><span class="tag">🌈 Cozy</span><span class="tag">${w.hatched||0} hatched</span></div><button class="world-open" data-action="open-world" data-id="${w.id}">Open world →</button></div></div></article>`}

