function worldCard(w){const t=THEMES[w.theme%THEMES.length];return `<article class="world-card" data-world="${w.id}"><div class="world-cover" style="--sky:${t[0]};--ground:${t[1]};--ground2:${t[2]}"><span class="cover-badge">${w.biomes.length} BIOME${w.biomes.length===1?'':'S'}</span><div class="landscape">🌳　🌷　🌳</div><div class="cover-egg">${w.cover}</div></div><div class="world-content"><div class="world-title-row"><h3>${esc(w.name)}</h3><button class="dots" data-action="world-menu" data-id="${w.id}">···</button></div><div class="world-meta">${w.biomes.length} biomes · ${w.eggs.length} eggs · ${w.animals.length} friends</div><div class="world-footer"><div class="mini-tags"><span class="tag">🌈 Cozy</span><span class="tag">${w.hatched||0} hatched</span></div><button class="world-open" data-action="open-world" data-id="${w.id}">Open world →</button></div></div></article>`}
function editorView(){const w=current();if(!w)return worldsView();const tabs=['biomes','eggs','friends','guards'];return `<div class="page-head"><div><button class="soft-btn" data-action="back">← My worlds</button><div class="eyebrow" style="margin-top:14px">WORLD WORKSHOP</div><h1>${esc(w.name)}</h1><p>Make this little place yours.</p></div><button class="primary-btn" data-action="play">▶ Play world</button></div><nav class="tabs">${tabs.map(t=>`<button class="tab ${state.tab===t?'active':''}" data-action="tab" data-tab="${t}">${({biomes:'🌿 Biomes',eggs:'🥚 Eggs',friends:'🐾 Friends',guards:'🛡️ Guards'})[t]}</button>`).join('')}</nav><section class="editor-panel">${state.tab==='biomes'?biomesView(w):listView(w,state.tab)}</section>`}
function biomesView(w){return `<div class="section-head"><div><h2>Your biomes</h2><p>Shape the places your friends call home.</p></div><button class="primary-btn" data-action="add-biome">＋ Add biome</button></div><div class="biome-grid">${w.biomes.map((b,i)=>`<article class="biome-card"><div class="biome-scene" style="--sky:${b.sky};--ground:${b.ground}"><span>${b.plants}</span><b>${i===0?'☀️':b.weather.split(' ')[0]}</b></div><div class="item-content"><h3>${esc(b.name)}</h3><p>${esc(b.weather)} · ${esc(b.time)}</p><button class="secondary-btn" data-action="edit-biome" data-id="${b.id}">Customize</button> <button class="soft-btn" data-action="delete-biome" data-id="${b.id}">Remove</button></div></article>`).join('')}</div>`}
function listView(w,type){const prop=type==='eggs'?'eggs':type==='friends'?'animals':'guards',items=w[prop]||[],isEgg=type==='eggs';return `<div class="section-head"><div><h2>${({eggs:'Buildable eggs',friends:'Your little friends',guards:'World protectors'})[type]}</h2><p>${isEgg?'Design shells, then hatch them in play mode.':'Edit every block and give each character a name.'}</p></div><button class="primary-btn" data-action="add-item" data-type="${type}">＋ Create ${isEgg?'egg':type==='friends'?'friend':'guard'}</button></div><div class="item-grid">${items.length?items.map(it=>`<article class="item-card"><div class="item-art" style="--item-color:${it.color||'#ffb98e'}">${isEgg?'🥚':'🐾'}<div class="mini-voxel">${voxel(it.blocks,48)}</div></div><div class="item-content"><h3>${esc(it.name)}</h3><p>${isEgg?`${it.shape} · ${it.rarity} · ${it.hatch}s to hatch`:`${it.rarity} ${type==='guards'?'protector':'friend'}`}</p><button class="secondary-btn" data-action="build-item" data-id="${it.id}" data-type="${type}">✏️ Edit blocks</button><button class="soft-btn" data-action="rename-item" data-id="${it.id}" data-type="${type}">Name</button></div></article>`).join(''):'<p class="empty-note">Nothing here yet — make your first one!</p>'}</div>`}
function voxel(blocks,unit=38){const cells=new Map((blocks||[]).map(b=>[`${b.x},${b.y}`,b]));const cols=7,rows=7;return `<div class="voxel-grid" style="--unit:${unit}px">${Array.from({length:cols*rows},(_,i)=>{let x=i%cols,y=Math.floor(i/cols),b=cells.get(`${x},${y}`);return `<button class="voxel ${b?'filled':''}" ${b?`style="--block:${b.c}"`:''} data-block="${x},${y}" aria-label="block ${x},${y}"></button>`}).join('')}</div>`}
function builderView(){const w=current(),item=getCurrentItem();if(!w||!item){state.page='editor';return editorView()}return `<div class="page-head"><div><button class="soft-btn" data-action="back-editor">← ${esc(item.name)}</button><div class="eyebrow" style="margin-top:12px">BLOCK STUDIO</div><h1>${esc(item.name)}</h1><p>Tap or drag across the grid to build.</p></div><button class="primary-btn" data-action="done-building">Done ✓</button></div><div class="builder-layout"><div class="builder-canvas"><div class="builder-preview">${voxel(item.blocks,42)}</div><p>Tap a block to paint · choose erase to remove</p></div><aside class="builder-tools"><label class="field-label">Name<input id="itemName" maxlength="24" value="${esc(item.name)}"></label><div class="tool-row"><button class="tool-btn ${tool==='paint'?'selected':''}" data-action="tool" data-tool="paint">🖌️ Paint</button><button class="tool-btn ${tool==='erase'?'selected':''}" data-action="tool" data-tool="erase">🧽 Erase</button></div><label class="field-label">Block color</label><div class="swatches">${COLORS.map(c=>`<button class="swatch ${color===c?'chosen':''}" style="--swatch:${c}" data-action="color" data-color="${c}" aria-label="${c}"></button>`).join('')}</div><input id="customColor" type="color" value="${color}" aria-label="Custom color"><label class="field-label">Shape <select id="shapeSelect"><option ${item.shape==='Round'?'selected':''}>Round</option><option ${item.shape==='Tall'?'selected':''}>Tall</option><option ${item.shape==='Square'?'selected':''}>Square</option></select></label>${item.hatch!==undefined?'<label class="field-label">Hatch time (seconds)<input id="hatchTime" type="range" min="10" max="90" value="'+item.hatch+'"></label>':''}<button class="soft-btn" data-action="undo">↶ Undo</button></aside></div>`}
function playView(){const w=current();if(!w)return worldsView();return `<div class="play-top"><div><button class="soft-btn" data-action="back">← Workshop</button><div class="eyebrow" style="margin-top:12px">NOW PLAYING</div><h1>${esc(w.name)}</h1></div><div class="coin-pill">🪙 <b id="coinCount">${w.coins}</b> coins</div></div><div class="play-scene"><div class="play-sky">☁️　　　　　　　 ☁️</div><div class="play-tree">🌳　🌼　🌳　🌷　🌳</div><div class="play-creatures">${w.animals.map(a=>`<button class="creature" data-action="pet" data-id="${a.id}"><span class="creature-icon">🐾</span><b>${esc(a.name)}</b></button>`).join('')}${w.eggs.map(e=>`<button class="creature egg-creature" data-action="hatch" data-id="${e.id}"><span class="creature-icon">🥚</span><b>${esc(e.name)}</b><small>${e.hatch||30}s to hatch</small></button>`).join('')}</div><div class="treadmill"><span>🏃‍♂️</span><div><b>Friend treadmill</b><small>Earn coins while your friends run!</small></div><button class="primary-btn" data-action="run">Run +${Math.max(1,w.treadmill)} 🪙</button></div></div><div class="play-panels"><section class="play-card"><div class="section-head"><div><h2>Egg nursery</h2><p>Tap an egg to hatch it into a friend.</p></div><span>🥚 ${w.eggs.length}</span></div><div class="nursery-row">${w.eggs.map(e=>`<button class="nursery-egg" data-action="hatch" data-id="${e.id}">🥚<small>${esc(e.name)}</small></button>`).join('')||'<span>No eggs yet. Build one in the workshop!</span>'}</div></section><section class="play-card"><div class="section-head"><div><h2>Cozy upgrades</h2><p>Spend coins to boost your world.</p></div><span>✨</span></div><div class="upgrade-row">${[['treadmill','Faster treadmill','🏃',10],['hatch','Quick hatch','🐣',15],['luck','Lucky friends','🍀',20]].map(([k,n,ico,cost])=>`<button class="upgrade" data-action="upgrade" data-upgrade="${k}"><span>${ico}</span><b>${n}</b><small>Level ${w.upgrades[k]||0} · ${cost*(1+(w.upgrades[k]||0))} coins</small></button>`).join('')}</div></section></div>${!localStorage.getItem('egg-tutorial-'+w.id)?`<div class="tutorial-card"><b>🌟 First time here?</b> Run your friends on the treadmill to earn coins, then hatch an egg and try upgrades! <button data-action="dismiss-tutorial" class="soft-btn">Got it</button></div>`:''}`}
function getCurrentItem(){const w=current();if(!w)return null;return [...w.eggs,...w.animals,...w.guards].find(i=>i.id===state.itemId)}

