function getCurrentItem(){const w=current();if(!w)return null;return [...w.eggs,...w.animals,...w.guards].find(i=>i.id===state.itemId)}
function bind(){document.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',handle));document.querySelectorAll('.world-card').forEach(el=>el.addEventListener('click',e=>{if(e.target.closest('[data-action]'))return;state.worldId=el.dataset.world;state.page='editor';state.tab='biomes';render()}));document.querySelectorAll('[data-block]').forEach(el=>el.addEventListener('click',e=>{e.stopPropagation();blockTap(e.currentTarget.dataset.block)}));const grid=document.querySelector('.voxel-grid');if(grid){grid.addEventListener('pointerover',e=>{if(e.buttons&&e.target.matches('[data-block]'))blockTap(e.target.dataset.block)})}document.getElementById('itemName')?.addEventListener('input',e=>{const it=getCurrentItem();if(it){it.name=e.target.value;save()}});document.getElementById('customColor')?.addEventListener('input',e=>{color=e.target.value});document.getElementById('shapeSelect')?.addEventListener('change',e=>{const it=getCurrentItem();if(it){it.shape=e.target.value;save()}});document.getElementById('hatchTime')?.addEventListener('input',e=>{const it=getCurrentItem();if(it){it.hatch=+e.target.value;save()}});document.querySelectorAll('.upgrade').forEach(el=>el.addEventListener('click',handle))}
function blockTap(pos){const it=getCurrentItem();if(!it)return;let[x,y]=pos.split(',').map(Number);history.push(JSON.stringify(it.blocks));const index=it.blocks.findIndex(b=>b.x===x&&b.y===y);if(tool==='erase'){if(index>=0)it.blocks.splice(index,1)}else if(index>=0){it.blocks[index].c=color}else{it.blocks.push({x,y,c:color,type:'shell'})}save();render()}
function modal(title,content){const root=document.getElementById('modalRoot');root.innerHTML=`<div class="modal-backdrop" data-action="close-modal"><section class="modal" onclick="event.stopPropagation()"><button class="modal-close" data-action="close-modal">×</button><h2>${title}</h2>${content}</section></div>`;root.querySelectorAll('[data-action="close-modal"]').forEach(b=>b.onclick=()=>root.innerHTML='')}
function handle(e){const b=e.currentTarget,act=b.dataset.action,w=current();if(act==='create-world'){modal('Create a little world',`<label class="field-label">World name<input id="worldName" maxlength="28" placeholder="My magical place" value=""></label><button class="primary-btn" data-action="confirm-world">Create world 🌱</button>`);return}if(act==='confirm-world'){const name=document.getElementById('worldName').value.trim()||'My little world';const nw=newWorld(name);worlds.unshift(nw);save();state.worldId=nw.id;state.page='editor';state.tab='biomes';document.getElementById('modalRoot').innerHTML='';render();return}if(act==='open-world'||act==='world-menu'){state.worldId=b.dataset.id;if(act==='open-world'){state.page='editor';state.tab='biomes';render()}else{const ww=current();modal(esc(ww.name),`<label class="field-label">Rename world<input id="renameWorld" maxlength="28" value="${esc(ww.name)}"></label><button class="primary-btn" data-action="save-world-name">Save name</button> <button class="soft-btn" data-action="delete-world">Delete world</button>`)}return}if(act==='save-world-name'){const nw=document.getElementById('renameWorld').value.trim();if(nw)w.name=nw;save();document.getElementById('modalRoot').innerHTML='';render();return}if(act==='delete-world'){if(worlds.length===1){alert('Keep at least one world to play!');return}if(confirm('Delete this world and everything in it?')){worlds=worlds.filter(x=>x.id!==state.worldId);save();document.getElementById('modalRoot').innerHTML='';state.page='worlds';render()}return}if(act==='back'){state.page='worlds';render();return}if(act==='back-editor'||act==='done-building'){save();state.page='editor';render();return}if(act==='tab'){state.tab=b.dataset.tab;render();return}if(act==='add-biome'){modal('Add a new biome',`<label class="field-label">Biome name<input id="biomeName" maxlength="24" value="Moonlit Garden"></label><button class="primary-btn" data-action="confirm-biome">Add biome</button>`);return}if(act==='confirm-biome'){const n=document.getElementById('biomeName').value.trim()||'New biome';w.biomes.push({id:id(),name:n,ground:'#a8d88e',sky:'#bce7e6',weather:'☀️ Sunny',time:'Day',plants:'🌼 🌿 🌷 🌳',music:'Gentle morning',eggs:[]});save();document.getElementById('modalRoot').innerHTML='';render();return}if(act==='delete-biome'){if(w.biomes.length<2){alert('Every world needs at least one biome!');return}w.biomes=w.biomes.filter(x=>x.id!==b.dataset.id);save();render();return}if(act==='edit-biome'){const bi=w.biomes.find(x=>x.id===b.dataset.id);modal('Customize biome',`<label class="field-label">Name<input id="biomeName" value="${esc(bi.name)}"></label><label class="field-label">Sky color<input id="skyColor" type="color" value="${bi.sky}"></label><label class="field-label">Ground color<input id="groundColor" type="color" value="${bi.ground}"></label><label class="field-label">Weather<select id="weather"><option>☀️ Sunny</option><option>🌧️ Rainy</option><option>❄️ Snowy</option><option>🌈 Rainbow</option></select></label><button class="primary-btn" data-action="save-biome" data-id="${bi.id}">Save biome</button>`);return}if(act==='save-biome'){const bi=w.biomes.find(x=>x.id===b.dataset.id);bi.name=document.getElementById('biomeName').value.trim()||bi.name;bi.sky=document.getElementById('skyColor').value;bi.ground=document.getElementById('groundColor').value;bi.weather=document.getElementById('weather').value;save();document.getElementById('modalRoot').innerHTML='';render();return}

